from enum import Enum


class TEST(Enum):
    """Test state"""
    START = "TEST->START"
    FINISHED = "TEST->FINISHED"
    RECOVERY = "EXECUTE->RECOVERY"
    HEARTBEAT = "HEARTBEAT"
    RESET_TEST_ENVIRONMENT = "TEST->RESET_TEST_ENVIRONMENT"
    COPY_SERVER_LOGS = "TEST->COPY_SERVER_LOGS"
    GET_SERVER_VERSION = "SERVER->GET_VERSION"
    CHECK_SERIAL = "TEST->CHECK_SERIAL"
    CHECK_COM_PORT = "TEST->CHECK_COM_PORT"


class QXDM(Enum):
    """QXDM state"""
    CONFIG = "QXDM->CONFIG"
    STOP = "QXDM->STOP"
    REBOOT = "QXDM->RESET_UE"
    ATTACH = "QXDM->ATTACH"
    DETACH = "QXDM->DETACH"
    GET_LOG_ITEMS = "QXDM->GET_LOG_ITEMS"
    GET_LOG_ITEM = "QXDM->GET_LOG_SINGLE_ITEM"
    CLEAR_CURRENT_LOG_ITEMS = "QXDM->CLEAR_CURRENT_LOG_ITEMS"
    SAVE_ISF = "QXDM->SAVE_ISF_FILE"
    COPY_LOGS = "QXDM->COPY_LOGS_TO_REMOTE"
    CLEAR_ALL_LOGS = "QXDM->CLEAR_ALL_QXDM_LOGS"
    GET_MEASUREMENT = "QXDM->GET_MEASUREMENT_AVERAGE_FROM_TIME_FRAME"
    READ_NV_ITEM = "QXDM->READ_NV_ITEM"
    WRITE_NV_ITEM = "QXDM->WRITE_NV_ITEM"


class THROUGHPUT(Enum):
    """Throughput state"""
    START = "THROUGHPUT->START"
    STOP = "THROUGHPUT->STOP"
    GET_STATISTICS = "THROUGHPUT->GET_STATISTICS"
    RESET_STATISTICS = "THROUGHPUT->RESET_STATISTICS"


class SFTP(Enum):
    """Sftp status"""
    GET = "SFTP->GET"
    PUT = "SFTP->PUT"


class ADB(Enum):
    """Adb state"""
    CMD = "ADB->CMD"
    SHELL_CMD = "ADB->SHELL_CMD"


class AT_SERIAL(Enum):
    """AT serial state"""
    EXEC_CMD = "AT_SERIAL->EXEC_CMD"


class MBMS_SESSION(Enum):
    """MBMS state"""
    START_RECEIVING = "MBMS_SESSION->START_RECEIVING"
    START_VERIFYING = "MBMS_SESSION->START_VERIFYING"
    STOP_VERIFYING = "MBMS_SESSION->STOP_VERIFYING"
    GET_STATISTICS = "MBMS_SESSION->GET_STATISTICS"
    RESET_STATISTICS = "MBMS_SESSION->RESET_STATISTICS"


class CUSTOM_COMMAND(Enum):
    """Custom command state"""
    EXEC_CMD = "CUSTOM_COMMANDS->EXEC_CUSTOM_SHELL_CMD"
